    end

    on_intel do
      url "https://github.com/karnull/tnotify/releases/download/v0.2.0/tnotify-macOS-intel"
      sha256 "ae0f0930cd5b32b2c443b157e35607f3db8d5d063142a9806f7404f84401b060"
    end
  end

  on_linux do
    on_arm do
